import{_ as a,o as i,c as e,ag as t}from"./chunks/framework.CmaAMB6e.js";const b=JSON.parse('{"title":"Linux 学习等级体系（L1-L5）","description":"","frontmatter":{},"headers":[],"relativePath":"linux/levels.md","filePath":"linux/levels.md","lastUpdated":null}'),d={name:"linux/levels.md"};function r(o,l,h,n,s,c){return i(),e("div",null,[...l[0]||(l[0]=[t(`<h1 id="linux-学习等级体系-l1-l5" tabindex="-1">Linux 学习等级体系（L1-L5） <a class="header-anchor" href="#linux-学习等级体系-l1-l5" aria-label="Permalink to &quot;Linux 学习等级体系（L1-L5）&quot;">​</a></h1><blockquote><p>每个技能独立走 5 级阶梯。等级衡量的是「能做什么」，不是「背过什么」。每学完一级用 <code>/assess &lt;技能&gt; &lt;等级&gt;</code> 让 AI 考核，达标后再进下一级。</p><p>等级 ↔ 阶段映射以各技能 <code>learning-path.md</code> 为准；本文件定义每级的<strong>能力目标、常见错误、晋升标准、考核题型</strong>。</p></blockquote><h2 id="等级总览" tabindex="-1">等级总览 <a class="header-anchor" href="#等级总览" aria-label="Permalink to &quot;等级总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>等级</th><th>名称</th><th>定位</th><th>对应阶段</th><th>考核最低分</th></tr></thead><tbody><tr><td>L1</td><td>新手入门</td><td>跑通最小程序，建立平台认知</td><td>阶段 1 · 基础层</td><td>80%</td></tr><tr><td>L2</td><td>基础能力者</td><td>掌握语言核心，能写独立功能</td><td>阶段 2 · 核心能力层</td><td>80%</td></tr><tr><td>L3</td><td>应用开发者</td><td>能独立开发完整应用/项目</td><td>阶段 3 · 工程层</td><td>80%</td></tr><tr><td>L4</td><td>资深开发者</td><td>能解决生产级问题（性能/崩溃/安全）</td><td>阶段 4 · 平台特性 + 资深层(前段)</td><td>82%</td></tr><tr><td>L5</td><td>专家/架构师</td><td>能设计架构、主导技术决策</td><td>资深层(后段) + 综合实战</td><td>85%</td></tr></tbody></table><blockquote><p>各技能的阶段划分不同（移动端有 UI 层、Linux 无），对应到 L2/L3 时以该技能 learning-path.md 的实际阶段为准。</p></blockquote><hr><h2 id="level-1-·-新手入门" tabindex="-1">Level 1 · 新手入门 <a class="header-anchor" href="#level-1-·-新手入门" aria-label="Permalink to &quot;Level 1 · 新手入门&quot;">​</a></h2><h3 id="能力目标" tabindex="-1">能力目标 <a class="header-anchor" href="#能力目标" aria-label="Permalink to &quot;能力目标&quot;">​</a></h3><ul><li>理解平台项目结构、构建与运行流程</li><li>掌握变量、类型、函数、控制流</li><li>能读懂并修复最简单报错</li><li>建立「写 → 报错 → 改」的闭环</li></ul><h3 id="常见错误" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误" aria-label="Permalink to &quot;常见错误&quot;">​</a></h3><ol><li>环境配置半途而废（下载慢/报错就放弃）</li><li><code>&gt;</code> 覆盖与 <code>&gt;&gt;</code> 追加混淆（<code>&gt;</code> 会清空原文件，不可逆）</li><li>相对路径与绝对路径写错，命令作用到错误位置</li><li>只读不写，没有动手闭环</li></ol><h3 id="晋升标准" tabindex="-1">晋升标准 <a class="header-anchor" href="#晋升标准" aria-label="Permalink to &quot;晋升标准&quot;">​</a></h3><ul><li>[ ] 独立创建项目并跑通第一个程序</li><li>[ ] 用本语言写一个「输入两数求和」程序</li><li>[ ] 能解释本平台可变/不可变语义</li><li>[ ] 通过 L1 考核</li></ul><hr><h2 id="level-2-·-基础能力者" tabindex="-1">Level 2 · 基础能力者 <a class="header-anchor" href="#level-2-·-基础能力者" aria-label="Permalink to &quot;Level 2 · 基础能力者&quot;">​</a></h2><h3 id="能力目标-1" tabindex="-1">能力目标 <a class="header-anchor" href="#能力目标-1" aria-label="Permalink to &quot;能力目标&quot;">​</a></h3><ul><li>集合/数据结构常用操作</li><li>异步编程模型（协程/async-await/Promise）</li><li>错误处理与空安全</li><li>理解不可变性与副作用</li></ul><h3 id="常见错误-1" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误-1" aria-label="Permalink to &quot;常见错误&quot;">​</a></h3><ol><li>主线程阻塞操作（移动端网络/文件阻塞 UI）</li><li>滥用强解包导致运行时崩溃</li><li>静默吞掉异常</li><li>不理解异步生命周期导致泄漏/状态错乱</li></ol><h3 id="晋升标准-1" tabindex="-1">晋升标准 <a class="header-anchor" href="#晋升标准-1" aria-label="Permalink to &quot;晋升标准&quot;">​</a></h3><ul><li>[ ] 实现一个「批量处理数据并输出」程序</li><li>[ ] 正确处理异步错误和空值（不崩溃、不静默）</li><li>[ ] 解释本平台异步模型的核心机制</li><li>[ ] 通过 L2 考核</li></ul><hr><h2 id="level-3-·-应用开发者" tabindex="-1">Level 3 · 应用开发者 <a class="header-anchor" href="#level-3-·-应用开发者" aria-label="Permalink to &quot;Level 3 · 应用开发者&quot;">​</a></h2><h3 id="能力目标-2" tabindex="-1">能力目标 <a class="header-anchor" href="#能力目标-2" aria-label="Permalink to &quot;能力目标&quot;">​</a></h3><ul><li>声明式 UI / 完整应用骨架</li><li>组件化、状态管理、列表、导航、表单</li><li>工程能力：网络、存储、依赖管理</li><li>测试意识（单元/集成/UI）</li></ul><h3 id="常见错误-2" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误-2" aria-label="Permalink to &quot;常见错误&quot;">​</a></h3><ol><li>状态管理混乱（该提升的没提升）</li><li>布局/组件嵌套过深</li><li>列表没有 key/复用机制</li><li>网络请求只有 happy path，缺 loading/错误态</li><li>测试只写 happy path</li></ol><h3 id="晋升标准-2" tabindex="-1">晋升标准 <a class="header-anchor" href="#晋升标准-2" aria-label="Permalink to &quot;晋升标准&quot;">​</a></h3><ul><li>[ ] 独立完成一个完整应用/项目（含列表/表单/持久化）</li><li>[ ] 能写出覆盖主要分支的测试</li><li>[ ] 能用调试工具定位并修复问题</li><li>[ ] 通过 L3 考核</li></ul><hr><h2 id="level-4-·-资深开发者" tabindex="-1">Level 4 · 资深开发者 <a class="header-anchor" href="#level-4-·-资深开发者" aria-label="Permalink to &quot;Level 4 · 资深开发者&quot;">​</a></h2><h3 id="能力目标-3" tabindex="-1">能力目标 <a class="header-anchor" href="#能力目标-3" aria-label="Permalink to &quot;能力目标&quot;">​</a></h3><ul><li>架构模式（MVVM/MVI 等）与分层</li><li>依赖注入</li><li>性能优化（重组/渲染/启动/并发）</li><li>崩溃与内存问题分析治理</li><li>平台特性深入（权限/通知/后台）</li></ul><h3 id="常见错误-3" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误-3" aria-label="Permalink to &quot;常见错误&quot;">​</a></h3><ol><li>架构过度设计，为了模式而用模式</li><li>性能优化方向错误，不打热点</li><li>内存泄漏/崩溃只临时绕过不根治</li><li>忽视边界条件与弱网/离线场景</li><li>安全合规遗漏（混淆/签名/权限）</li></ol><h3 id="晋升标准-3" tabindex="-1">晋升标准 <a class="header-anchor" href="#晋升标准-3" aria-label="Permalink to &quot;晋升标准&quot;">​</a></h3><ul><li>[ ] 为一个已有项目引入架构分层与依赖注入</li><li>[ ] 用 profiler 定位并修复一个真实性能问题</li><li>[ ] 解读一次线上崩溃并给出根治方案</li><li>[ ] 通过 L4 考核（含架构答辩 + 性能分析）</li></ul><hr><h2 id="level-5-·-专家-架构师" tabindex="-1">Level 5 · 专家/架构师 <a class="header-anchor" href="#level-5-·-专家-架构师" aria-label="Permalink to &quot;Level 5 · 专家/架构师&quot;">​</a></h2><h3 id="能力目标-4" tabindex="-1">能力目标 <a class="header-anchor" href="#能力目标-4" aria-label="Permalink to &quot;能力目标&quot;">​</a></h3><ul><li>独立设计应用架构并论证取舍</li><li>并发模型深入、安全加固与发布流程</li><li>国际化/无障碍/多设备适配</li><li>主导代码评审、生产事故复盘</li><li>沉淀自己的工程 checklist</li></ul><h3 id="常见错误-4" tabindex="-1">常见错误 <a class="header-anchor" href="#常见错误-4" aria-label="Permalink to &quot;常见错误&quot;">​</a></h3><ol><li>忽视平台差异化能力（如鸿蒙分布式）</li><li>不沉淀复盘，同样的坑反复踩</li><li>发布/签名/混淆流程不了解</li><li>无法权衡架构与业务复杂度</li></ol><h3 id="晋升标准-4" tabindex="-1">晋升标准 <a class="header-anchor" href="#晋升标准-4" aria-label="Permalink to &quot;晋升标准&quot;">​</a></h3><ul><li>[ ] 独立完成综合实战项目（含架构设计文档 + 性能/安全考量）</li><li>[ ] 能设计并论证一个完整架构方案</li><li>[ ] 能评审他人代码并给出建设性意见</li><li>[ ] 通过 L5 考核（项目答辩 + 代码评审）</li></ul><hr><h2 id="等级跃迁图" tabindex="-1">等级跃迁图 <a class="header-anchor" href="#等级跃迁图" aria-label="Permalink to &quot;等级跃迁图&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L1 新手 ─(跑通最小程序)→ L2 基础能力者 ─(独立功能)→ L3 应用开发者</span></span>
<span class="line"><span>    ─(完整项目)→ L4 资深开发者 ─(架构与治理)→ L5 专家/架构师</span></span></code></pre></div><h2 id="使用约定" tabindex="-1">使用约定 <a class="header-anchor" href="#使用约定" aria-label="Permalink to &quot;使用约定&quot;">​</a></h2><ol><li>每级学完用 <code>/assess &lt;技能&gt; &lt;等级&gt;</code> 考核，达标再升级</li><li>考核记录追加到该技能 <code>progress.md</code>，不覆盖历史</li><li>未通过时按 <code>assess</code> 给出的补学路径复习，不重复考试</li><li>L4/L5 考核包含架构答辩与代码评审，不只是选择题</li></ol>`,50)])])}const q=a(d,[["render",r]]);export{b as __pageData,q as default};
